/// <summary>
/// Data provider class for the MET PO Continuing Permission Notice report.
/// </summary>
/// <remarks>
/// This class is responsible for preparing and populating temporary data used in the Continuing Permission Notice SSRS report.
/// It extends <c>SrsReportDataProviderPreProcessTempDB</c>, enabling pre-processing logic to fill TempDB tables before report execution.
/// The <c>SRSReportParameterAttribute</c> binds this class to the <c>METPOContinuingPermissionNoticeContract</c>, which defines the report parameters.
/// Key responsibilities:
/// - Retrieve and transform purchase order and excise-related data.
/// - Populate temporary tables with enriched metadata for reporting.
/// - Support filtering and parameterization via the associated contract class.
/// </remarks>
[SRSReportParameterAttribute(classstr(METPOContinuingPermissionNoticeContract))]
class METPOContinuingPermissionNoticeDP extends SrsReportDataProviderPreProcessTempDB
{
    RecordInsertList insertList;
    METPOContinuingPermissionNoticeHeaderTmp header;
    METPOContinuingPermissionNoticeLineTmp line;
    PurchTable purchTable;
    METPOContinuingPermissionNoticeContract contract;

}

Method.Source:
/// <summary>
/// Executes the report data preparation logic for the Continuing Permission Notice.
/// </summary>
/// <remarks>
/// This method is called by the SSRS framework during report generation. It performs the following:
/// - Retrieves and processes purchase order and excise-related data.
/// - Populates the temporary table <c>METPOContinuingPermissionNoticeLineTmp</c> with enriched line-level details.
/// - Ensures all required fields are calculated and formatted for rendering in the report layout.
/// </remarks>
public void processReport()
{
    contract = this.parmDataContract() as METPOContinuingPermissionNoticeContract;

    PurchId purchId = contract.parmPurchId();
    purchTable = PurchTable::find(purchId);

    PurchLine purchLineNegative;

    select firstonly RecId from purchLineNegative
        where purchLineNegative.PurchId == purchTable.PurchId
        && purchLineNegative.PurchQty < 0;

    METPurchTable metPurchTable = METPurchTable::find(purchTable.PurchId);

    // Proceed only if:
    // - PurchTable record exists
    // - The order is marked as UnderBond
    // - There is at least one negative line (return)
    // - The vendor return flag is set
    if (purchTable.RecId && metPurchTable.UnderBond && purchLineNegative.RecId && metPurchTable.VendorReturn)
    {
        this.insertHeaderData();
    }
}

/// <summary>
/// Inserts the report header data.
/// </summary>
public void insertHeaderData()
{
    METVendTable vendTable = METVendTable::find(purchTable.OrderAccount);

    METCPNumber cpNumber = purchTable.metPurchTable().ContinuingPermissionNoticeNumber;

    if (!cpNumber)
    {
        NumberSequenceReference numberSequenceReference;

        numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METCPNumber));

        if (numberSequenceReference.RecId)
        {
            cpNumber = NumberSeq::newGetNum(numberSequenceReference).num();
        }
    }

    header.ContinuingPermissionNoticeNumber = cpNumber;

    CompanyInfo companyInfo = CompanyInfo::find();
    InventSite site;

    select firstonly METBondNumber from site
        where site.SiteId == purchTable.InventSiteId;

    InventLocation inventLocation;

    select firstonly METWHSubEntity, Name, RecId from inventLocation
        where inventLocation.InventLocationId == purchTable.InventLocationId;

    header.CompanyLogo = this.getCompanyLogo(companyInfo.METLegalEntityType, inventLocation.METWHSubEntity);
    LogisticsEntityPostalAddressView postalAddressView = this.getWareHousePrimaryAddress(inventLocation.RecId);

    METIndustryKeyTable industryKey = METIndustryKeyTable::find(inventLocation.METWHSubEntity);

    header.IndustryKey = industryKey.IndustryKey;

    header.SendingBranchAddress = postalAddressView.Address;
    header.SendingBranchName = inventLocation.Name;
    header.ReceivingBranchAddress = VendTable::find(purchTable.OrderAccount).postalAddress().Address;
    header.ReceivingBranchName = VendTable::find(purchTable.OrderAccount).name();
    header.NoticeDate = DateTimeUtil::date(DateTimeUtil::applyTimeZoneOffset(DateTimeUtil::getSystemDateTime(), DateTimeUtil::getUserPreferredTimeZone()));
    header.NoticeTimeString = int2Str(DateTimeUtil::time(DateTimeUtil::utcNow()));
    header.CompanyName = industryKey.CompanyName;

    List metBondList = strSplit(site.METBondNumber, ' ');
    Container metBondCon = list2con(metBondList);

    header.SenderBranchExciseNumber = conpeek(metBondCon, 2);
    header.SenderBranchBondNumber = conpeek(metBondCon, 1);
    header.ReceivingBranchExciseNumber = vendTable.ExciseNumber;
    header.ReceivingBranchBondNumber = vendTable.BondNumber;
    header.ReturnPurchaseOrder = purchTable.PurchId;
    header.InvoiceId = contract.parmInvoiceId();
    header.insert();

    METPurchTable metPurchTable;

    select firstonly metPurchTable
        where metPurchTable.PurchId == purchTable.PurchId;

    if (metPurchTable.RecId)
    {
        ttsbegin;
        // Update existing record
        metPurchTable.selectForUpdate(true);
        metPurchTable.ContinuingPermissionNoticeNumber = header.ContinuingPermissionNoticeNumber;
        metPurchTable.update();
        ttscommit;
    }
    else
    {
        // Insert new record
        metPurchTable.PurchId = purchTable.PurchId;
        metPurchTable.ContinuingPermissionNoticeNumber = header.ContinuingPermissionNoticeNumber;
        metPurchTable.insert();
    }

    this.insertLineData();
}

/// <summary>
/// Inserts temporary line records for purchase order continuing permission notice based on purchase lines and associated lodgement data.
/// </summary>
/// <remarks>
/// This method processes each purchase line in the current purchase order:
/// - If a lodgement is already recorded on the METPurchLine, it is split and used directly.
/// - If no lodgement exists, it calculates applicable lodgements using getMetLodgement(),
///   which returns a list of [Lodgement ID, Available Quantity] pairs.
/// Each lodgement entry is passed to prepareRecordListTmp() to populate the temporary table.
/// Finally, all records are inserted into the database using a RecordInsertList.
/// </remarks>
public void insertLineData()
{
    const str defaultUOM = 'EA';

    PurchLine purchLine;
    InventTable inventTable;
    InventDim inventDim;
    METInventTable metInventTable;
    METPurchLine metPurchLine;
    METTariffItemCodeBase tariffCodeBase;

    insertList = new RecordInsertList(tableNum(METPOContinuingPermissionNoticeLineTmp), false, false, false, false, false, line);

    while select purchLine
        where purchLine.PurchId == purchTable.PurchId
    join inventTable
        where purchLine.ItemId == inventTable.ItemId
    outer join metInventTable
        where metInventTable.ItemId == inventTable.ItemId
    outer join TariffItem from tariffCodeBase
        where tariffCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
    outer join RecId, InventSiteId from inventDim
        where inventDim.inventDimId == purchLine.InventDimId
    outer join RecId, Lodgement, BottleSupplied from metPurchLine
        where metPurchLine.PurchLine == purchLine.RecId
    {
        List lodgementList = new List(Types::Container);

        if (metPurchLine.Lodgement && metPurchLine.BottleSupplied)
        {
            // Split both strings into lists
            List lodgementSplit = strSplit(metPurchLine.Lodgement, ',');
            List bottleSplit = strSplit(metPurchLine.BottleSupplied, ',');

            ListEnumerator lodgementEnum = lodgementSplit.getEnumerator();
            ListEnumerator bottleEnum = bottleSplit.getEnumerator();

            // Pair each lodgement with its corresponding bottle quantity
            while (lodgementEnum.moveNext() && bottleEnum.moveNext())
            {
                METLodgement lodgementId = any2Str(lodgementEnum.current());
                real bottlesSupplied = str2num(any2Str(bottleEnum.current()));

                lodgementList.addEnd([lodgementId, bottlesSupplied]);
            }
        }
        else
        {
            // Calculate lodgements based on available excise inventory
            lodgementList = this.getMetLodgement(
            purchLine.ItemId,
            inventDim.InventSiteId,
            purchLine.QtyOrdered);
        }

        // Check if lodgementList has entries
        if (!lodgementList.empty())
        {
            // Iterate lodgementList and call prepareRecordListTmp for each entry
            ListEnumerator enum = lodgementList.getEnumerator();

            while (enum.moveNext())
            {
                container pair = enum.current();
                METLodgement lodgementId = conPeek(pair, 1);
                NumberOf bottleQty = conPeek(pair, 2);

                this.prepareRecordListTmp(purchLine,
                                        inventTable,
                                        metInventTable,
                                        tariffCodeBase,
                                        lodgementList,
                                        lodgementId,
                                        bottleQty,
                                        true,
                                        purchLine.QtyOrdered);
            }
        }
        else
        {
            // Handle case when lodgementList is empty
            List emptyList = new List(Types::Container);

            this.prepareRecordListTmp(purchLine,
                                    inventTable,
                                    metInventTable,
                                    tariffCodeBase,
                                    emptyList,
                                    '',    // Empty lodgementId
                                    0,     // Zero bottleQty
                                    false, // Indicates no lodgements
                                    purchLine.QtyOrdered);
        }
    }

    insertList.insertDatabase();
}

/// <summary>
/// dsHeader
/// </summary>
/// <returns>METPOContinuingPermissionNoticeHeaderTmp</returns>
[SRSReportDataSetAttribute(tableStr(METPOContinuingPermissionNoticeHeaderTmp))]
public METPOContinuingPermissionNoticeHeaderTmp dsHeader()
{
    select header;

    return header;
}

/// <summary>
/// dsLines
/// </summary>
/// <returns>METPOContinuingPermissionNoticeLineTmp</returns>
[SRSReportDataSetAttribute(tableStr(METPOContinuingPermissionNoticeLineTmp))]
public METPOContinuingPermissionNoticeLineTmp dsLines()
{
    select line;

    return line;
}

/// <summary>
/// Get METcash logo based on entity
/// </summary>
/// <param name = "_legalEntityType">LegalEntityType</param>
/// <param name = "_subEntityWareHouse">SubEntity warehouse</param>
/// <returns>Image</returns>
public container getCompanyLogo(METLegalEntityType _legalEntityType, InventLocationId _subEntityWareHouse)
{
    container image;

    switch (_legalEntityType)
    {
        case METLegalEntityType::Food:
            image = SysDocuBrandImages::getImage(_subEntityWareHouse);
            break;

        case METLegalEntityType::Liquor:
            image = SysDocuBrandImages::getImage(METConstants::LiquorLogo);
            break;

        default:
            break;

    }
    return image;
}

/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <param name = "_roleRecId">Role Recid</param>
/// <param name = "_type">LogisticsElectronicAddressMethodType</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}

/// <summary>
/// Prepares and inserts a temporary line record for the purchase order continuing permission notice.
/// </summary>
/// <param name="_purchLine">The purchase line being processed.</param>
/// <param name="_inventTable">The item master record associated with the purchase line.</param>
/// <param name="_metInventTable">Extended item metadata including bottle size, alcohol content, and pack quantity.</param>
/// <param name="_tariffCodeBase">Tariff item code details for customs and excise reporting.</param>
/// <param name="_lodgement">List of containers [Lodgement, BottlesSupplied].</param>
/// <param name="_isLodgement">Flag indicating whether lodgement logic is applied.</param>
/// <param name="_availableQty">Total available quantity (used only if _isLodgement is true).</param>
private void prepareRecordListTmp(
PurchLine _purchLine,
InventTable _inventTable,
METInventTable _metInventTable,
METTariffItemCodeBase _tariffCodeBase,
List _lodgement,
MetLodgement _metLodgement,
NumberOf _bottleQty,
boolean _isLodgement,
InventQty _availableQty = 0)
{
    const str defaultUOM = 'EA';

    METExciseRegisterEntry exciseRegister;
    METPurchLine metPurchLine;

    str lodgementStr = '';
    str bottleStr = '';

    // Loop through the lodgement list and build comma-separated strings
    // for both Lodgement IDs and Bottles Supplied. Also capture the last
    // lodgement for use in excise lookup and line population.
    ListEnumerator enum = _lodgement.getEnumerator();
    while (enum.moveNext())
    {
        container pair = enum.current();
        METLodgement lodgementId = conPeek(pair, 1);
        real bottleQty = conPeek(pair, 2);

        lodgementStr = lodgementStr == '' ? lodgementId : strFmt('%1,%2', lodgementStr, lodgementId);
        bottleStr = bottleStr == '' ? strFmt('%1', bottleQty) : strFmt('%1,%2', bottleStr, bottleQty);
    }

    // Update or insert the METPurchLine record with the combined lodgement
    // and bottle quantity strings. If the record exists, append to it;
    // otherwise, create a new one.
    if (!_lodgement.empty())
    {
        select firstonly metPurchLine
            where metPurchLine.PurchLine == _purchLine.RecId;

        if (metPurchLine.RecId)
        {
            ttsbegin;
            metPurchLine.selectForUpdate(true);
            metPurchLine.Lodgement = lodgementStr;
            metPurchLine.BottleSupplied = bottleStr;
            metPurchLine.update();
            ttscommit;
        }
        else
        {
            metPurchLine.PurchLine = _purchLine.RecId;
            metPurchLine.Lodgement = lodgementStr;
            metPurchLine.BottleSupplied = bottleStr;
            metPurchLine.insert();
        }
    }

    // Set BondMark using the last lodgement in the list
    line.BondMark = _metLodgement;

    // Retrieve excise register entry for the item and site using the last lodgement
    exciseRegister = METExciseRegisterEntry::find(
    _metLodgement,
    _purchLine.inventDim().InventSiteId,
    _purchLine.ItemId);

    // Convert purchase quantity to bottles using UOM conversion
    METPurchaseWMSFactor purchaseWMSFactor = UnitOfMeasureConversion::findByConversion(
    UnitOfMeasure::findBySymbol(_purchLine.PurchUnit).RecId,
    UnitOfMeasure::findBySymbol(defaultUOM).RecId,
    EcoResProduct::findByProductNumber(_purchLine.ItemId).RecId).Factor;

    // Populate the temporary line record with all required fields
    line.BottlesSupplied = _isLodgement ? abs(_bottleQty) : abs(purchaseWMSFactor * _purchLine.PurchQty);
    line.ItemId = _purchLine.ItemId;
    line.ItemDescription = _inventTable.productName(SystemParameters::getSystemLanguageId());
    line.BottleSize = _metInventTable.BottleSize;
    line.PackQty = _metInventTable.ItemPack;
    line.Strength = _metInventTable.AlcoholContent;
    line.PurchUoM = _purchLine.PurchUnit;
    line.Quantity = _purchLine.PurchQty;
    line.LitresOfAlcoholCalculated = abs(_metInventTable.BottleSize * line.BottlesSupplied * (_metInventTable.AlcoholContent / 100));
    line.ValueTIU = exciseRegister.TIUV;
    line.TariffItem = _tariffCodeBase.TariffItem;
    line.CountryOfOrigin = _metInventTable.CountryCode;
    line.StatCode = _metInventTable.statcode();
    line.ValueDuty = exciseRegister.DutyRateReceived;
    line.InvoiceAccount = purchTable.InvoiceAccount;
    line.PurchId = purchTable.PurchId;

    // Add the populated line to the insert list for batch processing
    insertList.add(line);
}

/// <summary>
/// Allocates purchase line quantity across open lodgements in chronological order.
/// Updates available quantity and lodgement status, and returns a list of [Lodgement ID, Bottles Supplied].
/// </summary>
/// <param name="_itemId">Item ID to allocate lodgements for.</param>
/// <param name="_siteId">Site ID where lodgements are stored.</param>
/// <param name="_purchLineQty">Quantity to be fulfilled from lodgements.</param>
/// <returns>
/// A List of containers, each containing [Lodgement ID, Bottles Supplied].
/// </returns>
private List getMetLodgement(ItemId _itemId, InventSiteId _siteId, Qty _purchLineQty)
{
    List resultList = new List(Types::Container);
    METExciseInformationTable metExciseInformationTablePO;
    real remainingQty = abs(_purchLineQty);

    ttsbegin;

    // Select open lodgements in chronological order
    while select forupdate metExciseInformationTablePO
        order by CreatedDateTime asc
            where (metExciseInformationTablePO.InventTransType == InventTransType::Purch ||
                metExciseInformationTablePO.InventTransType == InventTransType::TransferOrderReceive) &&
                metExciseInformationTablePO.ItemId == _itemId &&
                metExciseInformationTablePO.SiteId == _siteId &&
                metExciseInformationTablePO.AvailableQty > 0 &&
                metExciseInformationTablePO.LodgementClosed == NoYes::No &&
                metExciseInformationTablePO.Lodgement != ''
    {
        if (remainingQty <= 0)
        {
            break; // Stop if required quantity is fulfilled
        }

        real availableQtyBefore = metExciseInformationTablePO.AvailableQty;
        real bottlesSupplied = 0;

        if (remainingQty >= availableQtyBefore)
        {
            // Use full available quantity
            bottlesSupplied = availableQtyBefore;
            remainingQty -= availableQtyBefore;

            metExciseInformationTablePO.AvailableQty = 0;
            metExciseInformationTablePO.LodgementClosed = NoYes::Yes;
        }
        else
        {
            // Use partial quantity
            bottlesSupplied = remainingQty;
            metExciseInformationTablePO.AvailableQty = availableQtyBefore - remainingQty;
            remainingQty = 0;
        }

        metExciseInformationTablePO.update();

        // Add [Lodgement ID, Bottles Supplied] to result list
        resultList.addEnd([metExciseInformationTablePO.Lodgement, bottlesSupplied]);
    }

    ttscommit;

    return resultList;
}
